new_source_v421:
for name in ["cuml_quality_df", "cupy_df"]:
    candidate = globals().get(name)
    if (
        isinstance(candidate, pd.DataFrame)
        and len(candidate)
        and "quality_pass" in candidate.columns
    ):
        tmp = candidate.copy()
        tmp["section"] = name.replace("_quality_df", "").replace("_df", "")
        checks.append(tmp)
